from azure.ai.contentsafety import ContentSafetyClient
from azure.ai.contentsafety.models import AnalyzeTextOptions
from azure.core.credentials import AzureKeyCredential


def redact_unsafe(payload, config=None):
    config = config or {}
    with ContentSafetyClient(config['endpoint'], AzureKeyCredential(config['api_key'])) as client:
        response = client.analyze_text(AnalyzeTextOptions(text=payload['text'], output_type='EightSeverityLevels'))
        for category in response.categories_analysis:
            if category.severity > 4:
                payload['text'] = payload['text'].replace(category.text, '[REDACTED]')
    return payload

import os


def get_config():
    return {
        'endpoint': os.getenv('AZURE_CONTENT_SAFETY_ENDPOINT'),
        'api_key': os.getenv('AZURE_CONTENT_SAFETY_API_KEY')
    }


def get_client(config=None):
    config = config or get_config()
    return ContentSafetyClient(config['endpoint'], AzureKeyCredential(config['api_key']))

from typing import Dict, List


class AnalyzeTextOptions:
    def __init__(self, text: str, output_type: str):
        self.text = text
        self.output_type = output_type


class CategoryAnalysis:
    def __init__(self, severity: int, text: str):
        self.severity = severity
        self.text = text


class AnalyzeTextResponse:
    def __init__(self, categories_analysis: List[CategoryAnalysis]):
        self.categories_analysis = categories_analysis

